    # Pattern should be p, p+1, p+2, ..., 6, 1, 2, ...
    # Starting from first non-None position, find the expected pattern

    # Find first non-None position
    first_non_none = None
    for i, v in enumerate(pattern):
        if v is not None:
            first_non_none = i
            break

    if first_non_none is None:
        return True, "All zeros"

    # Find the pattern offset
    # value at position i should be ((i - first_non_none + start_offset - 1) % 6) + 1
    # We need to find start_offset

    for i, v in enumerate(pattern):
        if v is None:
            continue
        # Expected: if start_offset = start_val, then value = ((i - first_non_none + start_val - 1) % 6) + 1
        start_offset = v - ((i - first_non_none - 1) % 6)
